fn lm_271(mut in_txt: Tpl::Text, mut in_items: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>>, mut in_a_modelNamePrefixStr: ArcStr, mut in_a_header: Tpl::Text, mut in_a_sub: Tpl::Text) -> Result<(Tpl::Text, Tpl::Text, Tpl::Text)> {
    let mut out_txt: Tpl::Text;
    let mut out_a_header: Tpl::Text;
    let mut out_a_sub: Tpl::Text;
    (out_txt, out_a_header, out_a_sub) = (::match_deref::match_deref! { match &((in_txt.clone(), in_items.clone(), in_a_modelNamePrefixStr.clone(), in_a_header.clone(), in_a_sub.clone())) {
        (txt, Deref @ metamodelica::List::Nil, _, a_header, a_sub) => {
            (txt.clone(), a_header.clone(), a_sub.clone())
        },
        (txt, Deref @ metamodelica::List::Cons { head: i_eqn, tail: rest }, a_modelNamePrefixStr, a_header, a_sub) => {
            let mut txt = (*txt).clone();
            let mut a_header = (*a_header).clone();
            let mut a_sub = (*a_sub).clone();
            (txt, a_header, a_sub) = fun_270(txt.clone(), i_eqn.clone(), (a_modelNamePrefixStr.clone()).clone(), a_header.clone(), a_sub.clone())?;
            txt = Tpl::nextIter(txt.clone())?;
            (txt, a_header, a_sub) = lm_271(txt.clone(), rest.clone(), (a_modelNamePrefixStr.clone()).clone(), a_header.clone(), a_sub.clone())?;
            (txt.clone(), a_header.clone(), a_sub.clone())
        },
        _ => bail!("match: no arm matched"),
    } });
    Ok((out_txt, out_a_header, out_a_sub))
}

pub fn functionSetupMixedSystemsTemp(mut txt: Tpl::Text, mut a_allEquations: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>>, mut a_header: Tpl::Text, mut a_modelNamePrefixStr: ArcStr) -> Result<(Tpl::Text, Tpl::Text)> {
    let mut out_txt: Tpl::Text;
    let mut out_a_header: Tpl::Text;
    let mut l_sub: Tpl::Text;
    l_sub = Tpl::emptyTxt.clone();
    out_txt = Tpl::pushIter(txt.clone(), Arc::new(Tpl::IterOptions { startIndex0: 0, empty: None, separator: Some(Arc::new(Tpl::StringToken::ST_STRING_LIST { strList: list![(literal!("\n")).clone(), (literal!("\n")).clone()], lastHasNewLine: true })), alignNum: 0, alignOfset: 0, alignSeparator: Arc::new(openmodelica_susan::Tpl::StringToken::ST_NEW_LINE), wrapWidth: 0, wrapSeparator: Arc::new(openmodelica_susan::Tpl::StringToken::ST_NEW_LINE) }))?;
    (out_txt, out_a_header, l_sub) = lm_271(out_txt.clone(), a_allEquations.clone(), (a_modelNamePrefixStr.clone()).clone(), a_header.clone(), l_sub.clone())?;
    out_txt = Tpl::popIter(out_txt.clone())?;
    Ok((out_txt, out_a_header))
}

// NOTE: #[tailcall::tailcall] disabled: function body contains a `match_deref!{…}` match,
// and the tailcall rewriter cannot see arms hidden behind the macro's `Deref @` patterns.
fn lm_273(mut in_txt: Tpl::Text, mut in_items: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>>, mut in_a_modelNamePrefix: ArcStr) -> Result<Tpl::Text> {
    let mut out_txt: Tpl::Text;
    out_txt = (::match_deref::match_deref! { match &((in_txt.clone(), in_items.clone(), in_a_modelNamePrefix.clone())) {
        (txt, Deref @ metamodelica::List::Nil, _) => {
            txt.clone()
        },
        (txt, Deref @ metamodelica::List::Cons { head: i_eq @ Deref @ SimCode::SimEqSystem::SES_LINEAR { alternativeTearing: Some(_), .. }, tail: rest }, a_modelNamePrefix) => {
            let mut txt = (*txt).clone();
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING { value: (literal!("int ")).clone() }))?;
            txt = CodegenUtil::symbolName(txt.clone(), (a_modelNamePrefix.clone()).clone(), (literal!("eqFunction")).clone())?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING { value: (literal!("_")).clone() }))?;
            txt = CodegenUtilSimulation::equationIndex(txt.clone(), i_eq.clone())?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_STRING { value: (literal!("(DATA* data, threadData_t* threadData);")).clone() }))?;
            txt = Tpl::nextIter(txt.clone())?;
            txt = lm_273(txt.clone(), rest.clone(), (a_modelNamePrefix.clone()).clone())?;
            txt.clone()
        },
        (txt, Deref @ metamodelica::List::Cons { head: _, tail: rest }, a_modelNamePrefix) => {
            let mut txt = (*txt).clone();
            txt = lm_273(txt.clone(), rest.clone(), (a_modelNamePrefix.clone()).clone())?;
            txt.clone()
        },
        _ => bail!("match: no arm matched"),
    } });
    Ok(out_txt)
}

pub fn functionInitialLinearSystems(mut txt: Tpl::Text, mut a_linearSystems: Arc<metamodelica::List<Arc<SimCode::SimEqSystem>>>, mut a_modelNamePrefix: ArcStr) -> Result<Tpl::Text> {
    let mut out_txt: Tpl::Text;
    let mut l_linearbody: Tpl::Text;
    let mut l_globalConstraintsFunctions: Tpl::Text;
    let mut l_tempeqns: Tpl::Text;
    l_tempeqns = Tpl::emptyTxt.clone();
    l_tempeqns = Tpl::pushIter(l_tempeqns.clone(), Arc::new(Tpl::IterOptions { startIndex0: 0, empty: None, separator: Some(Arc::new(openmodelica_susan::Tpl::StringToken::ST_NEW_LINE)), alignNum: 0, alignOfset: 0, alignSeparator: Arc::new(openmodelica_susan::Tpl::StringToken::ST_NEW_LINE), wrapWidth: 0, wrapSeparator: Arc::new(openmodelica_susan::Tpl::StringToken::ST_NEW_LINE) }))?;
    l_tempeqns = lm_273(l_tempeqns.clone(), a_linearSystems.clone(), (a_modelNamePrefix.clone()).clone())?;
    l_tempeqns = Tpl::popIter(l_tempeqns.clone())?;
    l_globalConstraintsFunctions = Tpl::emptyTxt.clone();
    (l_linearbody, l_globalConstraintsFunctions) = functionInitialLinearSystemsTemp(Tpl::emptyTxt.clone(), a_linearSystems.clone(), (a_modelNamePrefix.clone()).clone(), l_globalConstraintsFunctions.clone())?;
    out_txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_LINE { line: (literal!("/* Prototypes for the strict sets (Dynamic Tearing) */\n")).clone() }))?;
    out_txt = Tpl::writeText(out_txt.clone(), l_tempeqns.clone())?;
    out_txt = Tpl::softNewLine(out_txt.clone())?;
    out_txt = Tpl::writeTok(out_txt.clone(), Arc::new(Tpl::StringToken::ST_STRING_LIST { strList: list![(literal!("\n")).clone(), (literal!("/* Global constraints for the casual sets */\n")).clone()], lastHasNewLine: true }))?;
    out_txt = Tpl::writeText(out_txt.clone(), l_globalConstraintsFunctions.clone())?;
    out_txt = Tpl::softNewLine(out_txt.clone())?;
    out_txt = Tpl::writeTok(out_txt.clone(), Arc::new(Tpl::StringToken::ST_STRING_LIST { strList: list![(literal!("/* function initialize linear systems */\n")).clone(), (literal!("void ")).clone()], lastHasNewLine: false }))?;
    out_txt = CodegenUtil::symbolName(out_txt.clone(), (a_modelNamePrefix.clone()).clone(), (literal!("initialLinearSystem")).clone())?;
    out_txt = Tpl::writeTok(out_txt.clone(), Arc::new(Tpl::StringToken::ST_STRING_LIST { strList: list![(literal!("(int nLinearSystems, LINEAR_SYSTEM_DATA* linearSystemData)\n")).clone(), (literal!("{\n")).clone(), (literal!("  /* linear systems */\n")).clone()], lastHasNewLine: true }))?;
    out_txt = Tpl::pushBlock(out_txt.clone(), Arc::new(Tpl::BlockType::BT_INDENT { width: 2 }))?;
    out_txt = Tpl::writeText(out_txt.clone(), l_linearbody.clone())?;
    out_txt = Tpl::softNewLine(out_txt.clone())?;
    out_txt = Tpl::popBlock(out_txt.clone())?;
    out_txt = Tpl::writeTok(out_txt.clone(), Arc::new(Tpl::StringToken::ST_STRING { value: (literal!("}")).clone() }))?;
    Ok(out_txt)
}

