fn fun_349(mut in_txt: Tpl::Text, mut in_a_eq: Arc<SimCode::SimEqSystem>, mut in_a_eqs: Tpl::Text, mut in_a_modelNamePrefixStr: ArcStr) -> Result<(Tpl::Text, Tpl::Text)> {
    let mut out_txt: Tpl::Text;
    let mut out_a_eqs: Tpl::Text;
    (out_txt, out_a_eqs) = (::match_deref::match_deref! { match &((in_txt.clone(), in_a_eq.clone(), in_a_eqs.clone(), in_a_modelNamePrefixStr.clone())) {
        (txt, Deref @ SimCode::SimEqSystem::SES_RESIDUAL { index: _, .. }, a_eqs, _) => {
            (txt.clone(), a_eqs.clone())
        },
        (txt, Deref @ SimCode::SimEqSystem::SES_FOR_RESIDUAL { index: _, .. }, a_eqs, _) => {
            (txt.clone(), a_eqs.clone())
        },
        (txt, Deref @ SimCode::SimEqSystem::SES_GENERIC_RESIDUAL { index: _, .. }, a_eqs, _) => {
            (txt.clone(), a_eqs.clone())
        },
        (txt, i_eq, a_eqs, a_modelNamePrefixStr) => {
            let mut txt = (*txt).clone();
            let mut a_eqs = (*a_eqs).clone();
            a_eqs = equation_impl(a_eqs.clone(), -1, -1, i_eq.clone(), SimCodeFunction::contextJacobian().clone(), (a_modelNamePrefixStr.clone()).clone(), false)?;
            txt = Tpl::writeTok(txt.clone(), Arc::new(Tpl::StringToken::ST_LINE { line: (literal!("/* local constraints */\n")).clone() }))?;
            txt = createLocalConstraints(txt.clone(), i_eq.clone())?;
            txt = Tpl::softNewLine(txt.clone())?;
            txt = equation_call(txt.clone(), i_eq.clone(), (a_modelNamePrefixStr.clone()).clone(), SimCodeFunction::contextJacobian().clone())?;
            (txt.clone(), a_eqs.clone())
        },
        _ => unreachable!("match_deref! exhaustiveness placeholder"),
    } });
    Ok((out_txt, out_a_eqs))
}

