            let mut a_varDecls = (*a_varDecls).clone();
            let mut a_auxFunction = (*a_auxFunction).clone();
            l_sub = Tpl::emptyTxt.clone();
            l_backupKnown = Tpl::pushIter(Tpl::emptyTxt.clone(), Arc::new(Tpl::IterOptions { startIndex0: 0, empty: None, separator: Some(Arc::new(openmodelica_susan::Tpl::StringToken::ST_NEW_LINE)), alignNum: 0, alignOfset: 0, alignSeparator: Arc::new(openmodelica_susan::Tpl::StringToken::ST_NEW_LINE), wrapWidth: 0, wrapSeparator: Arc::new(openmodelica_susan::Tpl::StringToken::ST_NEW_LINE) }))?;
            (l_backupKnown, l_sub, a_varDecls) = lm_774(l_backupKnown.clone(), i_alg_knownOutputCrefs.clone(), l_sub.clone(), a_varDecls.clone())?;
            l_backupKnown = Tpl::popIter(l_backupKnown.clone())?;
            l_stmts = Tpl::pushIter(Tpl::emptyTxt.clone(), Arc::new(Tpl::IterOptions { startIndex0: 0, empty: None, separator: Some(Arc::new(openmodelica_susan::Tpl::StringToken::ST_NEW_LINE)), alignNum: 0, alignOfset: 0, alignSeparator: Arc::new(openmodelica_susan::Tpl::StringToken::ST_NEW_LINE), wrapWidth: 0, wrapSeparator: Arc::new(openmodelica_susan::Tpl::StringToken::ST_NEW_LINE) }))?;
